import * as THREE from 'three';import {PIECES,missionById,dimensions,placePiece} from './balance-lab.js';import {disposeToyTree} from '../world/toy-kit.js';
export function buildProjection(width,height){const scale=Math.min((width-44)/10,(height-52)/7.5);return {width,height,scale,ox:width/2,oy:height-30};}
export const toBuildPoint=(p,point)=>({x:(point.x-p.ox)/p.scale,y:(p.oy-point.y)/p.scale});
export function hitBuild(blocks,point){return [...blocks].reverse().find(b=>{const d=dimensions(b);return Math.abs(point.x-b.x)<=d.w/2+.1&&point.y>=b.y-.1&&point.y<=b.y+d.h+.1;})?.id??null;}
export function buildTilt(s){return s.phase==='testing'?Math.sin(s.testTime/3.6*Math.PI*2)*missionById(s.mission).tilt:0;}
export function drawBuild(ctx,s,{selectedId=null,ghost=null,showCenter=false,analysis=null}={}){if(!ctx)return;const p=buildProjection(ctx.canvas.width,ctx.canvas.height),{width:w,height:h,scale:k,ox,oy}=p,m=missionById(s.mission);ctx.clearRect(0,0,w,h);ctx.fillStyle='#f5f0d9';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#dfdcc6';ctx.lineWidth=1;for(let x=-4;x<=4;x++){ctx.beginPath();ctx.moveTo(ox+x*k,18);ctx.lineTo(ox+x*k,oy);ctx.stroke();}for(let y=0;y<=7;y++){ctx.beginPath();ctx.moveTo(ox-4.5*k,oy-y*k);ctx.lineTo(ox+4.5*k,oy-y*k);ctx.stroke();ctx.fillStyle='#798772';ctx.font=`bold ${Math.max(14,k*.4)}px "Dormi Gentle Pen", sans-serif`;ctx.textAlign='left';ctx.fillText(String(y),4,oy-y*k-3);}if(m.height){ctx.strokeStyle='#b9953c';ctx.setLineDash([7,5]);ctx.beginPath();ctx.moveTo(ox-4.5*k,oy-m.height*k);ctx.lineTo(ox+4.5*k,oy-m.height*k);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#846921';ctx.font='bold 17px "Dormi Gentle Pen",sans-serif';ctx.fillText('높이 목표',ox+1.7*k,oy-m.height*k-8);}
 ctx.save();ctx.translate(ox,oy);ctx.rotate(-buildTilt(s)*Math.PI/180);ctx.translate(-ox,-oy);ctx.fillStyle='#c2d4d3';ctx.fillRect(ox-4.5*k,oy+1,9*k,24);for(const[a,b]of m.pads){ctx.fillStyle='#9fbba1';ctx.fillRect(ox+a*k,oy,(b-a)*k,24);ctx.fillStyle='#d3dfb7';ctx.fillRect(ox+a*k,oy-4,(b-a)*k,5);}
 const box=(b,preview=false)=>{const d=dimensions(b),x=ox+(b.x-d.w/2)*k,y=oy-(b.y+d.h)*k,fail=s.phase==='failed'&&s.result?.failure?.failedId===b.id;ctx.save();if(fail){ctx.translate(x+d.w*k/2,y+d.h*k);ctx.rotate(.17);ctx.translate(-x-d.w*k/2,-y-d.h*k);ctx.globalAlpha=.7;}if(preview)ctx.globalAlpha=.52;ctx.fillStyle=PIECES[b.type].color;ctx.fillRect(x,y,d.w*k,d.h*k);ctx.fillStyle='#ffffff55';ctx.fillRect(x+2,y+2,Math.max(0,d.w*k-4),Math.min(7,d.h*k*.2));ctx.strokeStyle=fail?'#b66347':selectedId===b.id?'#294f55':'#607969';ctx.lineWidth=selectedId===b.id?3:1.5;if(preview)ctx.setLineDash([6,4]);ctx.strokeRect(x,y,d.w*k,d.h*k);ctx.setLineDash([]);if(b.type==='heavy'){ctx.fillStyle='#384c58';ctx.font=`bold ${Math.min(25,d.h*k*.65)}px "Dormi Gentle Pen",sans-serif`;ctx.textAlign='center';ctx.fillText('3배',x+d.w*k/2,y+d.h*k*.72);}ctx.restore();};
 for(const b of s.blocks)box(b);if(ghost){const candidate={...s,phase:'editing'},next=placePiece(candidate,ghost.type,ghost.x,ghost.rot,ghost.id);if(next.blocks!==candidate.blocks){const b=next.blocks.find(b=>ghost.id?b.id===ghost.id:b.id==='b'+next.serial);if(b)box(b,true);}}
 if(s.phase==='testing'||s.phase==='complete'){const payload=s.result?.checks[0]?.payload;if(payload){ctx.fillStyle='#aa86a4';ctx.fillRect(ox-.5*k,oy-(payload.y+.25)*k,k,.5*k);ctx.fillStyle='#fff7e7';ctx.font='bold 19px "Dormi Gentle Pen",sans-serif';ctx.textAlign='center';ctx.fillText('3',ox,oy-payload.y*k+6);}}
 if(showCenter&&analysis?.mass){const c=analysis.center;ctx.strokeStyle='#a1514b';ctx.setLineDash([5,4]);ctx.beginPath();ctx.moveTo(ox+c.x*k,oy-c.y*k);ctx.lineTo(ox+c.x*k,oy);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#b75e57';ctx.beginPath();ctx.arc(ox+c.x*k,oy-c.y*k,6,0,Math.PI*2);ctx.fill();for(const c of analysis.contacts){ctx.strokeStyle='#ba8437';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(ox+c.lo*k,oy-c.y*k);ctx.lineTo(ox+c.hi*k,oy-c.y*k);ctx.stroke();}}
 ctx.restore();return p;
}
export function createBalanceBoard(){const root=new THREE.Group();root.name='balance.board';let layer=null,key='',alive=true;const materials=new Map(),mat=c=>{if(!materials.has(c))materials.set(c,new THREE.MeshStandardMaterial({color:c,roughness:.85}));return materials.get(c);};function clear(){if(!layer)return;layer.traverse(o=>o.geometry?.dispose());layer.removeFromParent();layer.clear();}
 function update(s){if(!alive)return;const signature=s.mission+JSON.stringify(s.blocks);if(signature!==key){clear();key=signature;layer=new THREE.Group();root.add(layer);const add=(w,h,d,c,x,y,z,name)=>{const mesh=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat(c));mesh.position.set(x,y,z);mesh.name=name;mesh.castShadow=mesh.receiveShadow=true;layer.add(mesh);return mesh;};add(9.4,.12,2.4,'#a9c4c3',0,-.1,0,'balance.platform');for(const[a,b]of missionById(s.mission).pads)add(b-a,.12,2,'#a7bf9b',(a+b)/2,0,0,'balance.ground');for(const b of s.blocks){const d=dimensions(b);add(d.w,d.h,.78,PIECES[b.type].color,b.x,b.y+d.h/2+.06,0,'balance.'+b.id);}}
 layer.rotation.z=buildTilt(s)*Math.PI/180;for(const b of s.blocks){const mesh=layer.getObjectByName('balance.'+b.id);mesh.rotation.z=s.phase==='failed'&&s.result?.failure?.failedId===b.id?-.17:0;}}
 return {root,update,dispose(){if(!alive)return;alive=false;clear();for(const m of materials.values())m.dispose();root.clear();}};
}
